extends SceneTree
## Task 67 / P1: MEAN tables of the stone albedo arrays AS THE GPU HOLDS THEM. The sheets are compressed with both codecs of the
## web build (S3TC desktop, ETC2 phones) and decompressed again; the table is the average of the two codecs' linear means per layer
## (dark layers differ by 2-3 % between codecs, so one table for both stays inside +-2 %). Rewrites the MEAN block of
## world/looks/stone_tex.gd and prints per-codec deviation.
## Run: godot --headless --path . -s res://.orchestra/tasks/67/tex/measure_means.gd   (after build_sheets.py)

const SHEETS := [["stone_t1_albedo", 3, 6, 512], ["stone_t2_albedo", 4, 12, 256]]
const GD := "res://world/looks/stone_tex.gd"


func _lin(c: float) -> float:
	return c / 12.92 if c <= 0.04045 else pow((c + 0.055) / 1.055, 2.4)


func _mean(img: Image) -> Vector3:
	var lut := PackedFloat32Array()
	lut.resize(256)
	for i in 256:
		lut[i] = _lin(i / 255.0)
	var d := img.get_data()
	var s := Vector3.ZERO
	var n := d.size() / 4
	for p in n:
		s += Vector3(lut[d[p * 4]], lut[d[p * 4 + 1]], lut[d[p * 4 + 2]])
	return s / n


func _init() -> void:
	var out_f := {}
	var out_v := {}
	for sh in SHEETS:
		var sheet := Image.load_from_file(ProjectSettings.globalize_path("res://world/looks/tex/" + sh[0] + ".png"))
		sheet.convert(Image.FORMAT_RGBA8)
		var sz: int = sh[3]
		var f := PackedStringArray()
		var v := PackedStringArray()
		for i in sh[2]:
			var acc := Vector3.ZERO
			var per := []
			for codec in [Image.COMPRESS_S3TC, Image.COMPRESS_ETC2]:
				var layer := sheet.get_region(Rect2i((i % sh[1]) * sz, (i / sh[1]) * sz, sz, sz))
				layer.compress(codec, Image.COMPRESS_SOURCE_GENERIC)
				layer.decompress()
				layer.convert(Image.FORMAT_RGBA8)
				var m := _mean(layer)
				per.append(m)
				acc += m
			acc /= 2.0
			var luma := acc.dot(Vector3(0.2126, 0.7152, 0.0722))
			f.append("%.5f" % luma)
			v.append("Vector3(%.5f, %.5f, %.5f)" % [acc.x, acc.y, acc.z])
			print("%s[%d] mean %.5f  S3TC/avg %.4f  ETC2/avg %.4f" % [sh[0], i, luma, per[0].dot(Vector3(0.2126, 0.7152, 0.0722)) / luma, per[1].dot(Vector3(0.2126, 0.7152, 0.0722)) / luma])
		out_f[sh[0]] = "[" + ", ".join(f) + "]"
		out_v[sh[0]] = "[" + ", ".join(v) + "]"
	var s := FileAccess.get_file_as_string(GD)
	var a := s.find("# BEGIN MEANS")
	var b := s.find("# END MEANS")
	var block := "# BEGIN MEANS (measured after S3TC and ETC2 compression, averaged: .orchestra/tasks/67/tex/measure_means.gd)\n"
	block += "const MEAN_T1: PackedFloat32Array = %s\nconst MEAN_T2: PackedFloat32Array = %s\n" % [out_f["stone_t1_albedo"], out_f["stone_t2_albedo"]]
	block += "const MEAN_T1_RGB: PackedVector3Array = %s\nconst MEAN_T2_RGB: PackedVector3Array = %s\n" % [out_v["stone_t1_albedo"], out_v["stone_t2_albedo"]]
	s = s.substr(0, a) + block + s.substr(b)
	var fh := FileAccess.open(GD, FileAccess.WRITE)
	fh.store_string(s)
	fh.close()
	quit()
EOF
