vec3 crystal_cube(vec3 world_dir) {
	vec3 c = texture(world_cube, world_dir).rgb;
	return c * c * 4.0;
}

float crystal_hash(vec3 p) {
	p = fract(p * 0.3183099 + 0.1);
	p *= 17.0;
	return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
