// The flat face: view-space normal turned to the camera `nv`; planar uv (metres) of the object-space position on the
// dominant axis of the face `uv`; the uv frame in view space `tv`, `bv` (unit); the object-space face normal `nt`.
void crystal_face(vec3 vtx, vec3 tp, out vec3 nv, out vec3 nt, out vec2 uv, out vec3 tv, out vec3 bv) {
	vec3 dp1 = dFdx(vtx);
	vec3 dp2 = dFdy(vtx);
	nv = normalize(cross(dp1, dp2));
	nt = cross(dFdx(tp), dFdy(tp));
	if (dot(nv, -vtx) < 0.0) {
		nv = -nv;
		nt = -nt;
	}
	nt = nt / max(length(nt), 1e-9);
	vec3 an = abs(nt);
	uv = (an.x >= an.y && an.x >= an.z) ? tp.zy : ((an.y >= an.z) ? tp.xz : tp.xy);
	vec2 duv1 = dFdx(uv);
	vec2 duv2 = dFdy(uv);
	vec3 dp1perp = cross(nv, dp2);
	vec3 dp2perp = cross(dp1, nv);
	tv = dp2perp * duv1.x + dp1perp * duv2.x;
	bv = dp2perp * duv1.y + dp1perp * duv2.y;
	float inv = inversesqrt(max(max(dot(tv, tv), dot(bv, bv)), 1e-12));
	tv *= inv;
	bv *= inv;
}

float crystal_fresnel(float ndv, float f0) {
	return f0 + (1.0 - f0) * pow(1.0 - clamp(ndv, 0.0, 1.0), 5.0);
}

// The hackle ripple of a conchoidal fresh face: the perturbed normal (view space); `fresh` = 0 returns nv untouched.
vec3 crystal_hackle(vec3 nv, vec2 uv, vec3 tv, vec3 bv, out float height) {
	height = 0.5;
	if (fresh < 0.5) {
		return nv;
	}
	vec4 hk = texture(hackle_tex, uv * hackle_scale);
	height = hk.a;
	vec2 xy = (hk.xy * 2.0 - 1.0) * hackle_k;
	return normalize(nv + tv * xy.x + bv * xy.y);
}
